import json
from pathlib import Path
import run

original = run.bench.measure

def cgroup():
    return {key: int(value) for key, value in (line.split() for line in Path('/sys/fs/cgroup/cpu.stat').read_text().splitlines())}

def measure(command, output, pid=None):
    before = cgroup()
    process = run.bench.psutil.Process(pid) if pid else None
    worker_before = process.cpu_times()._asdict() if process else {}
    io_before = process.io_counters()._asdict() if process else {}
    result = original(command, output, pid)
    after = cgroup()
    if process:
        worker_after = process.cpu_times()._asdict()
        io_after = process.io_counters()._asdict()
        result['worker_cpu_delta'] = {key:worker_after[key]-value for key,value in worker_before.items()}
        result['worker_io_delta'] = {key:io_after[key]-value for key,value in io_before.items()}
    result['cgroup_cpu_delta'] = {key: after[key]-value for key, value in before.items()}
    output.write_text(json.dumps(result, indent=2)+'\n')
    return result

run.bench.measure = measure
run.app()
